def _cyclic_permutations(lst: Any) -> object {
    if (lst == []) {
        return [[]];
    }
    plst = [];
    for _ in range(len(lst)) {
        plst.append(lst);
        lst = lst[1:] + [lst[0]];
    }
    return plst;
}

